import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.BPaanrMb.js";const h=JSON.parse('{"title":"AI autonomous-driving answer protocol","description":"A fixed procedure for AI agents to classify, diagnose, validate and cite autonomous-driving problems in WheelOS.","frontmatter":{"title":"AI autonomous-driving answer protocol","description":"A fixed procedure for AI agents to classify, diagnose, validate and cite autonomous-driving problems in WheelOS.","status":"Repository fact","content_type":"methodology","keywords":["AI agent","troubleshooting","citation","evidence","product specification"]},"headers":[],"relativePath":"en/knowledge/answer-protocol.md","filePath":"en/knowledge/answer-protocol.md","lastUpdated":1794551845000}'),i={name:"en/knowledge/answer-protocol.md"};function s(r,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="ai-autonomous-driving-answer-protocol" tabindex="-1">AI autonomous-driving answer protocol <a class="header-anchor" href="#ai-autonomous-driving-answer-protocol" aria-label="Permalink to &quot;AI autonomous-driving answer protocol&quot;">​</a></h1><p>When AI uses this knowledge base to design a solution, analyze a fault, or evaluate a product, it must follow this sequence. The goal is to prevent unverified speculation from becoming a factual claim.</p><h2 id="_1-define-the-problem-object" tabindex="-1">1. Define the problem object <a class="header-anchor" href="#_1-define-the-problem-object" aria-label="Permalink to &quot;1. Define the problem object&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Required information</th></tr></thead><tbody><tr><td>Behavior</td><td>What the vehicle or system actually did</td></tr><tr><td>Expectation</td><td>What it should have done</td></tr><tr><td>Frequency</td><td>Every time, intermittent, scenario-specific or unreproducible</td></tr><tr><td>Boundary</td><td>Vehicle/simulation, speed, weather, map and sensor set</td></tr><tr><td>Version</td><td>WheelOS commit, module version and configuration version</td></tr><tr><td>Data</td><td>Topics, timestamps, coordinate frames, logs and replay</td></tr><tr><td>Content state</td><td>Product specification, repository fact, design guidance or existing evidence</td></tr><tr><td>Risk</td><td>Actuators, road safety or irreversible actions involved</td></tr></tbody></table><p>If critical fields are missing, request the missing data before giving a deterministic solution.</p><h2 id="_2-follow-the-data-path" tabindex="-1">2. Follow the data path <a class="header-anchor" href="#_2-follow-the-data-path" aria-label="Permalink to &quot;2. Follow the data path&quot;">​</a></h2><p>Find the first layer where behavior departs from expectations:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sensors -&gt; drivers -&gt; messages -&gt; time synchronization -&gt; coordinate transforms</span></span>
<span class="line"><span>        -&gt; localization / perception / prediction -&gt; planning -&gt; control -&gt; chassis feedback</span></span></code></pre></div><p>Do not assume the root cause is in planning because the visible symptom appears there.</p><h2 id="_3-design-the-smallest-experiment" tabindex="-1">3. Design the smallest experiment <a class="header-anchor" href="#_3-design-the-smallest-experiment" aria-label="Permalink to &quot;3. Design the smallest experiment&quot;">​</a></h2><p>Change one critical variable at a time, preserve a baseline, define numerical thresholds, record complete versions and configuration, and keep both successful and failing samples. Prefer replayable, automatable and low-risk environments before increasing the validation level.</p><h2 id="_4-output-format" tabindex="-1">4. Output format <a class="header-anchor" href="#_4-output-format" aria-label="Permalink to &quot;4. Output format&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Page type: product / knowledge / evidence / roadmap / community</span></span>
<span class="line"><span>Finding: product specification / repository fact / design guidance / partially verified / verified / planned / currently unknown</span></span>
<span class="line"><span>Evidence: page URL, evidence ID, repository commit or formal product specification</span></span>
<span class="line"><span>Approach: concrete change and reproduction steps</span></span>
<span class="line"><span>Result: metrics, baseline, sample size and raw artifacts</span></span>
<span class="line"><span>Boundary: uncovered hardware, scenarios, versions and safety limits</span></span>
<span class="line"><span>Next step: smallest additional experiment</span></span></code></pre></div><p><code>Verified</code> may cite only a record in <code>evidence/registry.json</code>. Without an evidence ID, do not use phrases such as &quot;WheelOS has verified&quot; or &quot;proven on a real vehicle&quot;. <code>Product specification</code> may describe configuration and delivery scope, but cannot be upgraded to a verification conclusion.</p><h2 id="_5-bilingual-and-conflict-handling" tabindex="-1">5. Bilingual and conflict handling <a class="header-anchor" href="#_5-bilingual-and-conflict-handling" aria-label="Permalink to &quot;5. Bilingual and conflict handling&quot;">​</a></h2><ul><li>Chinese and English pages must preserve the same facts, numbers, status, and limitations.</li><li>If versions conflict, report both URLs instead of choosing the more favorable statement.</li><li>Product specifications, evidence records and knowledge pages answer different questions. Do not merge them into a single &quot;verified&quot; conclusion.</li></ul>`,16)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
